import 'package:flutter/material.dart'; import '../models/keyboard_inspection_result.dart';
class KeyboardResultScreen extends StatelessWidget { final KeyboardInspectionResult result; const KeyboardResultScreen({super.key,required this.result}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Kết quả kiểm tra bàn phím')),body:ListView(padding:const EdgeInsets.all(16),children:[if(result.needsReview) const Card(child:Padding(padding:EdgeInsets.all(12),child:Text('Cần kiểm tra thủ công'))),Text(result.hasDefect?'Đã phát hiện lỗi ngoại quan.':'Không phát hiện lỗi ngoại quan trong ảnh'),...result.defects.map((d)=>ListTile(title:Text('${d['type']} — ${d['severity']}'),subtitle:Text('${d['reason'] ?? ''}\nĐộ tin cậy: ${d['confidence'] ?? ''}')))]));}
